prices = {"яблоко": 50, "банан": 70}
empty = {}
print(prices)

prices = {"яблоко": 50, "банан": 70}
print(prices["яблоко"])   # 50
print(prices["киви"])     # ошибка!

prices = {"яблоко": 50}
print(prices.get("киви"))       # None
print(prices.get("киви", 0))    # 0 — по умолчанию

prices = {"яблоко": 50, "банан": 70}
for name, price in prices.items():
    print(name, price)

words = ["да", "нет", "да"]
counts = {}
for w in words:
    counts[w] = counts.get(w, 0) + 1
print(counts)    # {'да': 2, 'нет': 1}

d = {}
d[(1, 2)] = "клетка"    # кортеж — можно
d[[1, 2]] = "ошибка"   # TypeError: unhashable

prices = {"яблоко": 50}
print(prices["киви"])        # KeyError — берите get
for k in prices:
    prices["новый"] = 1       # RuntimeError: размер изменился
